        "progress": "人脑从万维空间中涌现（图源：格原万维） 文｜胡香赟 编辑｜海若镜 人脑，是自然界演化出的最复杂的系统之一。 成年人脑只有两个拳头大小，但容纳了近860亿个神经元及同等数量的非神经元细胞，它们彼此连通，织就庞大繁复的脑网络，承载起人类全部的智能、情感、记忆和自我意识。这套系统如此精妙，以至于人脑最大的悖论是，我们的大脑不够聪明去理解如此聪明的大脑。 那么，AI能做得更好吗？ 这是卢萌过去15年来一直想做的事。从2011年赴剑桥大学读博,到2024年回国前担任高级研究员，卢萌一直主攻神经退行性疾病研究。遵循传统神经科学",
